      advantages: [
        "For applications that require enhanced ventilation.",
        "Designed for use with the Innorack IVC Mouse.",
        "For use with Innocage® mouse bottoms.",
        "100% PET plastic. BPA-Free."
      ]
    },
    "MSX2": {
      preTitle: "EMERGENCY",
      title: "MSX2",
      description: "A low-profile ventilation area static mouse lid with large dual Uniblend filter areas and metal grates for use in emergencies. It fits into the Innovive standard IVC rack in the event of a power failure.",
      imageSrc: "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/763d99886bdb63f30abca0bf213bc338e7495af0.png",
      advantages: [
        "Designed for emergency preparedness to operate without electricity.",
        "For use with Innocage® bottoms.",
        "100% PET plastic. BPA-Free."
      ]
    },
    "MVX3": {
      preTitle: "CONTAINMENT",
      title: "MVX3",
      description: "IVC mouse lid with dual Temish HEPA filters and blue grate for use in containment applications.",
      imageSrc: "https://inno.myvoladolabs.com/wp-content/uploads/2026/06/e5bcdc7ab6c22502d70c9f8307caf21528a2ffa2.png",
      advantages: [
